const { Client } = require('/usr/local/lib/node_modules/n8n/node_modules/pg');
const body = $input.item.json.body || {};
const studentCode = (body.student_code || '').trim();
const message = (body.message || '').trim();
let convId = body.conversation_id || null;

// 1. VALIDACIÓN DE ENTRADA Y GUARDRAILS DE SEGURIDAD
if (!studentCode) {
  return [{
    json: {
      success: false,
      conversation_id: convId,
      student_code: '',
      response: 'Error: Debe proporcionar el código del estudiante (student_code).',
      intent: 'validation_error',
      source: 'guardrail',
      timestamp: new Date().toISOString()
    }
  }];
}

if (!message) {
  return [{
    json: {
      success: false,
      conversation_id: convId,
      student_code: studentCode,
      response: 'Error: El mensaje de consulta no puede estar vacío.',
      intent: 'validation_error',
      source: 'guardrail',
      timestamp: new Date().toISOString()
    }
  }];
}

if (message.length > 500) {
  return [{
    json: {
      success: false,
      conversation_id: convId,
      student_code: studentCode,
      response: 'Tu mensaje excede el límite permitido de 500 caracteres. Por favor sintetiza tu inquietud.',
      intent: 'guardrail_blocked',
      source: 'guardrail',
      timestamp: new Date().toISOString()
    }
  }];
}

const lowerMsg = message.toLowerCase();
const injectionKeywords = ['password', 'contraseña', 'api_key', 'apikey', 'secret', 'drop table', 'delete from', 'ignore previous', 'ignora las instrucciones'];
if (injectionKeywords.some(kw => lowerMsg.includes(kw))) {
  return [{
    json: {
      success: false,
      conversation_id: convId,
      student_code: studentCode,
      response: 'Por razones de seguridad y privacidad, no puedo procesar consultas sobre credenciales o comandos del sistema.',
      intent: 'guardrail_blocked',
      source: 'guardrail',
      timestamp: new Date().toISOString()
    }
  }];
}

// 2. CONEXIÓN Y CONSULTA A POSTGRESQL
const client = new Client({
  host: 'chatbot_db',
  port: 5432,
  user: 'chatbot_admin',
  password: 'Chatbot_UNAB_LocalPass_2026!',
  database: 'chatbot_unab'
});

await client.connect();

try {
  // 2.1 Verificar existencia del estudiante
  const resEst = await client.query(
    `SELECT e.id_estudiante, e.codigo_estudiante, e.nombre_completo, p.nombre_programa, pe.id_plan, pe.version_plan, pe.nombre_plan
     FROM estudiantes e
     JOIN programas p ON e.id_programa = p.id_programa
     JOIN estudiante_plan_estudio epe ON epe.id_estudiante = e.id_estudiante AND epe.estado_asignacion = 'ACTIVO'
     JOIN planes_estudio pe ON epe.id_plan = pe.id_plan
     WHERE e.codigo_estudiante = $1`,
    [studentCode]
  );

  if (resEst.rows.length === 0) {
    await client.end();
    return [{
      json: {
        success: false,
        conversation_id: convId,
        student_code: studentCode,
        response: `El código de estudiante '${studentCode}' no se encuentra registrado en el sistema universitario UNAB.`,
        intent: 'student_not_found',
        source: 'postgresql',
        timestamp: new Date().toISOString()
      }
    }];
  }

  const student = resEst.rows[0];
  const idEstudiante = student.id_estudiante;
  const idPlan = student.id_plan;
  const nombreEst = student.nombre_completo;
  const programaEst = student.nombre_programa;
  const planEst = student.version_plan;

  // 2.2 Gestión de Conversación en Memoria Persistente
  if (!convId) {
    const resConv = await client.query(
      `INSERT INTO conversaciones (id_estudiante, titulo_conversacion, estado_conversacion)
       VALUES ($1, $2, 'ACTIVA') RETURNING id_conversacion`,
      [idEstudiante, `Consulta: ${message.substring(0, 30)}...`]
    );
    convId = parseInt(resConv.rows[0].id_conversacion, 10);
  }

  // Registrar mensaje del usuario
  await client.query(
    `INSERT INTO mensajes (id_conversacion, remitente, contenido_texto, tokens_usados)
     VALUES ($1, 'ESTUDIANTE', $2, $3)`,
    [convId, message, Math.ceil(message.length / 4)]
  );

  // 2.3 CLASIFICACIÓN DE INTENCIÓN Y EJECUCIÓN DE CONSULTA SQL ESPECÍFICA
  let intent = 'general_chat';
  let responseText = '';

  if (lowerMsg.includes('aprobada') || lowerMsg.includes('pasé') || lowerMsg.includes('gané')) {
    intent = 'approved_subjects';
    const q = await client.query(
      `SELECT m.codigo_materia, m.nombre_materia, h.nota_final, pa.codigo_periodo
       FROM historial_academico h
       JOIN materias m ON h.id_materia = m.id_materia
       JOIN periodos_academicos pa ON h.id_periodo = pa.id_periodo
       WHERE h.id_estudiante = $1 AND h.estado_materia = 'APROBADA'
       ORDER BY h.semestre_cursado ASC`,
      [idEstudiante]
    );
    if (q.rows.length === 0) {
      responseText = `Hola ${nombreEst}. Aún no registras materias aprobadas en tu expediente.`;
    } else {
      const lista = q.rows.map(r => `• ${r.codigo_materia} - ${r.nombre_materia} (Nota: ${r.nota_final}, Periodo: ${r.codigo_periodo})`).join('\n');
      responseText = `¡Hola ${nombreEst}! Tienes ${q.rows.length} materia(s) APROBADA(S) en tu plan ${planEst}:\n\n${lista}`;
    }
  } else if (lowerMsg.includes('reprobada') || lowerMsg.includes('perdí') || lowerMsg.includes('perdi')) {
    intent = 'failed_subjects';
    const q = await client.query(
      `SELECT m.codigo_materia, m.nombre_materia, h.nota_final, h.numero_intento, pa.codigo_periodo
       FROM historial_academico h
       JOIN materias m ON h.id_materia = m.id_materia
       JOIN periodos_academicos pa ON h.id_periodo = pa.id_periodo
       WHERE h.id_estudiante = $1 AND h.estado_materia = 'REPROBADA'`,
      [idEstudiante]
    );
    if (q.rows.length === 0) {
      responseText = `¡Excelente noticia, ${nombreEst}! No tienes ninguna materia reprobada en tu historial académico.`;
    } else {
      const lista = q.rows.map(r => `• ${r.codigo_materia} - ${r.nombre_materia} (Intento ${r.numero_intento}, Nota: ${r.nota_final})`).join('\n');
      responseText = `Hola ${nombreEst}. Registras ${q.rows.length} materia(s) REPROBADA(S):\n\n${lista}\n\nTe sugerimos solicitar tutoría académica o matricularla en el siguiente periodo.`;
    }
  } else if (lowerMsg.includes('pendiente') || lowerMsg.includes('me falta') || lowerMsg.includes('faltan')) {
    intent = 'pending_subjects';
    const q = await client.query(
      `SELECT pm.semestre_sugerido, m.codigo_materia, m.nombre_materia, m.creditos
       FROM plan_materias pm
       JOIN materias m ON pm.id_materia = m.id_materia
       WHERE pm.id_plan = $1 AND pm.id_materia NOT IN (
           SELECT id_materia FROM historial_academico WHERE id_estudiante = $2 AND estado_materia = 'APROBADA'
       )
       ORDER BY pm.semestre_sugerido, m.nombre_materia`,
      [idPlan, idEstudiante]
    );
    const lista = q.rows.map(r => `• Semestre ${r.semestre_sugerido}: ${r.codigo_materia} - ${r.nombre_materia} (${r.creditos} cr)`).join('\n');
    responseText = `Hola ${nombreEst}. Tienes ${q.rows.length} materia(s) PENDIENTE(S) por cursar en tu pensum ${planEst}:\n\n${lista}`;
  } else if (lowerMsg.includes('en curso') || lowerMsg.includes('viendo') || lowerMsg.includes('matriculada')) {
    intent = 'current_subjects';
    const q = await client.query(
      `SELECT m.codigo_materia, m.nombre_materia, m.creditos, pa.codigo_periodo
       FROM historial_academico h
       JOIN materias m ON h.id_materia = m.id_materia
       JOIN periodos_academicos pa ON h.id_periodo = pa.id_periodo
       WHERE h.id_estudiante = $1 AND h.estado_materia = 'EN_CURSO'`,
      [idEstudiante]
    );
    if (q.rows.length === 0) {
      responseText = `Hola ${nombreEst}. Actualmente no registras materias activas en curso.`;
    } else {
      const lista = q.rows.map(r => `• ${r.codigo_materia} - ${r.nombre_materia} (${r.creditos} cr)`).join('\n');
      responseText = `Hola ${nombreEst}. Tienes ${q.rows.length} materia(s) EN CURSO este periodo:\n\n${lista}`;
    }
  } else if (lowerMsg.includes('promedio') || lowerMsg.includes('gpa') || lowerMsg.includes('acumulado')) {
    intent = 'gpa';
    const q = await client.query(
      `SELECT ROUND(SUM(h.nota_final * m.creditos) / NULLIF(SUM(m.creditos), 0), 2) AS gpa
       FROM historial_academico h
       JOIN materias m ON h.id_materia = m.id_materia
       WHERE h.id_estudiante = $1 AND h.nota_final IS NOT NULL`,
      [idEstudiante]
    );
    const gpaVal = q.rows[0].gpa || '0.00';
    responseText = `Hola ${nombreEst}. Tu promedio acumulado (GPA) actual es de ${gpaVal} / 5.00 en ${programaEst}.`;
  } else if (lowerMsg.includes('crédito') || lowerMsg.includes('credito')) {
    intent = 'credits_approved';
    const q = await client.query(
      `SELECT COALESCE(SUM(m.creditos), 0) AS total_aprobados
       FROM historial_academico h
       JOIN materias m ON h.id_materia = m.id_materia
       WHERE h.id_estudiante = $1 AND h.estado_materia = 'APROBADA'`,
      [idEstudiante]
    );
    const creds = q.rows[0].total_aprobados;
    responseText = `Hola ${nombreEst}. Has completado y aprobado un total de ${creds} créditos académicos en tu plan ${planEst}.`;
  } else if (lowerMsg.includes('avance') || lowerMsg.includes('porcentaje')) {
    intent = 'academic_progress';
    const q = await client.query(
      `SELECT COALESCE(SUM(m.creditos), 0) AS aprobados
       FROM historial_academico h
       JOIN materias m ON h.id_materia = m.id_materia
       WHERE h.id_estudiante = $1 AND h.estado_materia = 'APROBADA'`,
      [idEstudiante]
    );
    const apr = parseInt(q.rows[0].aprobados, 10);
    const pct = ((apr / 21) * 100).toFixed(2);
    responseText = `Hola ${nombreEst}. Tu avance académico en ${programaEst} (${planEst}) es del ${pct}% (${apr} de 21 créditos DEMO).`;
  } else if (lowerMsg.includes('cursar') || lowerMsg.includes('proyectar') || lowerMsg.includes('disponible')) {
    intent = 'available_subjects';
    const q = await client.query(
      `WITH materias_aprobadas AS (
           SELECT DISTINCT id_materia FROM historial_academico WHERE id_estudiante = $1 AND estado_materia = 'APROBADA'
       ),
       materias_pendientes AS (
           SELECT pm.id_materia, pm.semestre_sugerido
           FROM plan_materias pm
           WHERE pm.id_plan = $2 AND pm.id_materia NOT IN (SELECT id_materia FROM materias_aprobadas)
       )
       SELECT m.codigo_materia, m.nombre_materia, mp.semestre_sugerido, m.creditos
       FROM materias_pendientes mp
       JOIN materias m ON mp.id_materia = m.id_materia
       WHERE NOT EXISTS (
           SELECT 1 FROM prerrequisitos pr
           WHERE pr.id_plan = $2 AND pr.id_materia = mp.id_materia AND pr.tipo_requisito = 'PRERREQUISITO'
             AND pr.id_materia_requisito NOT IN (SELECT id_materia FROM materias_aprobadas)
       )`,
      [idEstudiante, idPlan]
    );
    const lista = q.rows.map(r => `• ${r.codigo_materia} - ${r.nombre_materia} (Semestre ${r.semestre_sugerido}, ${r.creditos} cr)`).join('\n');
    responseText = `Hola ${nombreEst}. Según tus materias aprobadas, estás habilitado para matricular:\n\n${lista}`;
  } else {
    intent = 'general_chat';
    responseText = `¡Hola ${nombreEst}! Soy el Asistente Académico de Ingeniería de Sistemas UNAB. Cuentas con plan activo ${planEst}. Puedes consultarme sobre tus materias aprobadas, reprobadas, pendientes, promedio acumulado o materias disponibles para matricular.`;
  }

  // Registrar respuesta del asistente en memoria persistente
  await client.query(
    `INSERT INTO mensajes (id_conversacion, remitente, contenido_texto, tokens_usados)
     VALUES ($1, 'ASISTENTE', $2, $3)`,
    [convId, responseText, Math.ceil(responseText.length / 4)]
  );

  await client.end();

  return [{
    json: {
      success: true,
      conversation_id: convId,
      student_code: studentCode,
      response: responseText,
      intent: intent,
      source: 'postgresql_structured',
      timestamp: new Date().toISOString()
    }
  }];
} catch (err) {
  await client.end();
  return [{
    json: {
      success: false,
      conversation_id: convId,
      student_code: studentCode,
      response: `Error al procesar la consulta académica: ${err.message}`,
      intent: 'db_error',
      source: 'postgresql',
      timestamp: new Date().toISOString()
    }
  }];
}
